"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["39561"],{59178(e){e.exports=JSON.parse('{"id":"F325","slug":"option-payoffs","name":"Call and Put Payoffs and Profit","subject":"Derivatives","section":"Derivatives","topic":"Option payoffs and profit diagrams","level":"Beginner","aliases":["option profit","breakeven","long call","short call","long put","short put","payoff diagram"],"formula":{"latex":"\\\\text{Call payoff}=\\\\max(S_{T}-K,0),\\\\quad \\\\text{Put payoff}=\\\\max(K-S_{T},0)","also":[],"text":"Call payoff = max(Spot at expiry - Strike, 0); Put payoff = max(Strike - Spot at expiry, 0); Profit = Payoff - Premium paid (a seller\'s profit is the opposite)"},"symbols":[{"symbol":"S_T","meaning":"Price of the underlying at expiry","unit":"money"},{"symbol":"K","meaning":"Strike price","unit":"money"},{"symbol":"Premium","meaning":"Price paid for the option today","unit":"money"}],"when_to_use":"Use it to draw or calculate the result of holding an option to expiry. The buyer\'s loss is limited to the premium. The seller\'s loss on a call is unlimited, and on a put it is limited to the strike minus the premium. The breakeven is where profit crosses zero.","worked_example":{"problem":"A call and a put both have a strike of 50. The call cost 3.20 and the put cost 2.10. The stock ends at 55. What are the payoffs, profits and breakevens?","inputs":{"st":55,"k":50,"pc":3.2,"pp":2.1},"steps":[{"label":"Call payoff = max(ST - K, 0)","working":"max(55-50, 0)","value":"5.00"},{"label":"Call buyer profit = payoff - premium","working":"5-3.2","value":"1.80"},{"label":"Put payoff = max(K - ST, 0)","working":"max(50-55, 0)","value":"0.00"},{"label":"Put buyer profit = payoff - premium","working":"0-2.1","value":"-2.10"},{"label":"Call breakeven = K + premium","working":"50+3.2","value":"53.20"},{"label":"Put breakeven = K - premium","working":"50-2.1","value":"47.90"}],"answer":"The call pays 5.00 for a profit of 1.80 to the buyer and a loss of the same size to the seller. The put expires worthless, so the buyer loses the premium of 2.10 (profit -2.10) and the seller keeps it. The call breaks even at 53.20 and the put at 47.90."},"calculator":{"available":true,"inputs":[{"id":"st","label":"Price at expiry","unit":"money","type":"number","default":55,"hint":""},{"id":"k","label":"Strike price","unit":"money","type":"number","default":50,"hint":""},{"id":"pc","label":"Call premium","unit":"money","type":"number","default":3.2,"hint":""},{"id":"pp","label":"Put premium","unit":"money","type":"number","default":2.1,"hint":""}],"checks":[],"steps":[{"id":"cp","label":"Call payoff = max(ST - K, 0)","expr":"max(st-k, 0)","format":"money"},{"id":"cprofit","label":"Call buyer profit = payoff - premium","expr":"cp-pc","format":"money"},{"id":"pay_put","label":"Put payoff = max(K - ST, 0)","expr":"max(k-st, 0)","format":"money"},{"id":"pprofit","label":"Put buyer profit = payoff - premium","expr":"pay_put-pp","format":"money"},{"id":"bec","label":"Call breakeven = K + premium","expr":"k+pc","format":"money"},{"id":"bep","label":"Put breakeven = K - premium","expr":"k-pp","format":"money"}],"results":["cp","cprofit","pprofit","bec","bep"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"cp":5,"cprofit":1.8,"pay_put":0,"pprofit":-2.1,"bec":53.2,"bep":47.9}},"finder":{"finds":"What an option pays at expiry and the profit after cost","needs":"Strike, price at expiry, premiums"},"related":[{"slug":"option-intrinsic-time-value","name":"Option Intrinsic Value and Time Value"},{"slug":"put-call-parity","name":"Put-Call Parity"},{"slug":"straddle-strangle","name":"Straddle and Strangle"}],"related_ids":["F324","F326","F329"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Call\xa0payoff</mtext><mo>=</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><msub><mi>S</mi><mi>T</mi></msub><mo>\u2212</mo><mi>K</mi><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Put\xa0payoff</mtext><mo>=</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>K</mi><mo>\u2212</mo><msub><mi>S</mi><mi>T</mi></msub><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Call payoff}=\\\\max(S_{T}-K,0),\\\\quad \\\\text{Put payoff}=\\\\max(K-S_{T},0)</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Call\xa0payoff</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Call payoff}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><msub><mi>S</mi><mi>T</mi></msub><mo>\u2212</mo><mi>K</mi><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\max(S_{T}-K,0)</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Put\xa0payoff</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Put payoff}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>K</mi><mo>\u2212</mo><msub><mi>S</mi><mi>T</mi></msub><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\max(K-S_{T},0)</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"buyout-value-creation","name":"Buyout Returns and Value Creation Bridge"},"next":{"slug":"callable-bond-value","name":"Callable and Putable Bond Value"},"lesson":null,"total":522}')}}]);